// v1 — original shape

GET /v1/users/42
→ { "name": "Rahul Sharma", "email": "rahul@example.com" }

// v2 — restructured, new fields added

GET /v2/users/42
→ { "id": 42, "profile": { "name": "Rahul Sharma", "email": "..." }, "role": "admin" }

// Both versions live simultaneously
// Old clients keep using v1, new clients use v2
// Deprecate v1 only after giving clients time to migrate

